<?php
namespace App\Http\Controllers;use App\Models\Order;use App\Services\PaymentService;use Illuminate\Http\Request;
class PaymentController extends Controller{public function show(string $uuid){$order=Order::where('uuid',$uuid)->firstOrFail();$this->guard($order);return view('storefront.payment',compact('order'));}public function initiate(Request $r,string $uuid,PaymentService $service){$v=$r->validate(['method'=>['required','in:cod,bkash,nagad,sslcommerz,worldwide']]);$order=Order::where('uuid',$uuid)->firstOrFail();$this->guard($order);try{$result=$service->initiate($order,$v['method']);return redirect()->to($result['redirect']);}catch(\RuntimeException $e){return back()->withErrors(['payment'=>$e->getMessage()]);}}public function complete(string $uuid){$order=Order::where('uuid',$uuid)->firstOrFail();$this->guard($order);return view('storefront.payment-complete',compact('order'));}private function guard(Order $order):void{abort_unless(session('last_order_uuid')===$order->uuid||auth()->id()===$order->user_id,403);}}
